import json
import sys
from datetime import datetime, timezone, timedelta


def parse_offset_aware(s):
    """Parse an offset-aware ISO8601 datetime string. Returns None for naive/invalid."""
    if not isinstance(s, str):
        return None
    try:
        # Python 3.7+ fromisoformat handles most ISO 8601 offsets
        dt = datetime.fromisoformat(s)
        # Must be offset-aware (have tzinfo with a non-zero offset or UTC)
        if dt.tzinfo is None:
            return None  # naive — skip
        return dt
    except (ValueError, TypeError):
        return None


def format_utc(dt):
    """Format a datetime as YYYY-MM-DDTHH:MM:SSZ in UTC."""
    utc_dt = dt.astimezone(timezone.utc)
    return utc_dt.strftime("%Y-%m-%dT%H:%M:%SZ")


def main():
    with open(sys.argv[1], "r") as f:
        data = json.load(f)

    as_of_raw = data.get("as_of")
    if not isinstance(as_of_raw, str):
        print("[]")
        return

    as_of = parse_offset_aware(as_of_raw)
    if as_of is None:
        print("[]")
        return

    reminders = data.get("reminders", [])
    results = []

    for r in reminders:
        # Skip completed reminders
        if r.get("completed", False):
            continue

        due_raw = r.get("due")
        # Skip null, missing, or naive due values
        if due_raw is None:
            continue
        due = parse_offset_aware(due_raw)
        if due is None:
            continue

        # Compare actual instants, not strings
        if due <= as_of:
            results.append({
                "id": r["id"],
                "title": r["title"],
                "due_utc": format_utc(due),
                "_due_dt": due,  # for sorting, removed later
            })

    # Sort by actual due instant, then by id
    results.sort(key=lambda x: (x["_due_dt"], x["id"]))

    # Remove the internal sorting key
    for item in results:
        del item["_due_dt"]

    print(json.dumps(results))


if __name__ == "__main__":
    main()
